 * the organization name limit, the display name is shortened until the whole
 * name fits, so it still ends in the suffix and the settings form can save it.
 */
function firstWorkspaceName(displayName: string): string {
  const room = ORGANIZATION_NAME_MAX - WORKSPACE_SUFFIX.length;
  return `${Array.from(displayName).slice(0, room).join("")}${WORKSPACE_SUFFIX}`;
}

