 * below the minimum length falls back to `workspace`, and `uniqueSlug()` then
 * skips reserved words and suffixes collisions (`admin` becomes `admin-2`).
 */
async function firstWorkspaceSlug(displayName: string): Promise<string> {
  const derived = slugify(displayName);
  const base =
    derived.length >= SLUG_MIN_LENGTH ? derived : FALLBACK_WORKSPACE_SLUG;
  return uniqueSlug(base, await orgRepo.listTakenOrgSlugs(base));
}

